--
-- Triggers `studenti`
--
DELIMITER $$
CREATE TRIGGER `tg_genera_matricola` BEFORE INSERT ON `studenti` FOR EACH ROW BEGIN
    DECLARE anno_corrente INT;
    DECLARE ultimo_progressivo INT;

    -- Preleva l'anno corrente come numero (es. 2026)
    SET anno_corrente = YEAR(NOW());

    -- Trova il valore massimo progressivo per l'anno in corso.
    -- Esempio: 20260005 % 10000 restituisce il progressivo 5.
    SELECT COALESCE(MAX(matricola % 10000), 0)
    INTO ultimo_progressivo
    FROM studenti
    WHERE matricola DIV 10000 = anno_corrente;

    -- Incrementa il progressivo di 1
    SET ultimo_progressivo = ultimo_progressivo + 1;

    -- Compone la nuova matricola numerica: (2026 * 10000) + 1 = 20260001
    SET NEW.matricola = (anno_corrente * 10000) + ultimo_progressivo;
SET @ultima_matricola_generata = NEW.matricola;
END
$$
DELIMITER ;

